using System;using System.Collections.Generic;using System.Linq;public class Graph{private Dictionary<int, List<int>> adjacencyList;public Graph(){adjacencyList = new Dictionary<int, List<int>>();}public void AddEdge(int source, int destination){if(!adjacencyList.ContainsKey(source)){adjacencyList[source] = new List<int>();}adjacencyList[source].Add(destination);}public List<int> DepthFirstSearch(int startVertex){List<int> visited = new List<int>();HashSet<int> visitedSet = new HashSet<int>();DFSUtil(startVertex, visited, visitedSet);return visited;}private void DFSUtil(int vertex, List<int> visited, HashSet<int> visitedSet){if(!adjacencyList.ContainsKey(vertex) || visitedSet.Contains(vertex)){return;}visited.Add(vertex);visitedSet.Add(vertex);if(adjacencyList.ContainsKey(vertex)){foreach(int neighbor in adjacencyList[vertex]){DFSUtil(neighbor, visited, visitedSet);}}}}